/**
 * RunRecs gap-fill for confirmed-missing 2026–2027 road/trail races.
 * Only events whose live RunRecs search was empty and whose race-day
 * date is published by the organiser (or AIMS / official tourism page).
 * Deduped by name+date+city against the existing catalogue merge.
 */
import type { Edition, Series } from "./types";

const CHECKED_AT = "2026-09-03";

function officialEntry(
  code: string,
  name: string,
  url: string,
  notes: string,
): Edition["entryOptions"] {
  return [
    {
      providerCode: code,
      providerName: name,
      entryUrl: url,
      entryType: "official",
      status: "open",
      checkedAt: CHECKED_AT,
      sourceUrl: url,
      isVerified: true,
      isPrimary: true,
      notes,
    },
  ];
}

